=# Incidente Registrado en GLPI - Joyería Lumière
- **ID Ticket GLPI:** #{{ $json.id }}
- **Fecha:** {{ $now.toFormat('dd/MM/yyyy HH:mm:ss') }}
- **Área / Categoría ITIL:** {{ $('Code in JavaScript').item.json.areaNombre }}
- **Título:** {{ $('Code in JavaScript').item.json.titulo }}
- **Detalle:**
{{ $('Code in JavaScript').item.json.descripcion }}

parameters.jsCode:
const body = $input.first().json.body || $input.first().json;

// 1. Validar estructura JSON de Grafana / Alertmanager
if (!body || !Array.isArray(body.alerts) || body.alerts.length === 0) {
  return [{ json: { valido: false, motivo: "Payload JSON inválido: falta el arreglo 'alerts'." } }];
}

// 2. Procesar únicamente alertas activas ('firing')
if (body.status && body.status !== 'firing') {
  return [{ json: { valido: false, motivo: `Alerta ignorada (estado: ${body.status}).` } }];
}

const alerta = body.alerts[0];
const labels = alerta.labels || {};
const annotations = alerta.annotations || {};

const nombreAlerta = labels.alertname || "Incidente Automatizado";
const severidad = (labels.severity || "warning").toLowerCase();
const servicio = labels.job || labels.container || labels.instance || "Infraestructura";
const resumen = annotations.summary || annotations.description || "Alerta disparada desde monitoreo sin descripción adicional.";
const textoCompleto = `${nombreAlerta} ${servicio} ${resumen}`.toLowerCase();

// 3. Asignar Categoría ITIL real de GLPI según el área afectada
let categoriaId = 4;
let areaNombre = "Alertas Automáticas (Prometheus / n8n)";

if (textoCompleto.includes("jwt") || textoCompleto.includes("owasp") || textoCompleto.includes("mercadopago") || textoCompleto.includes("seguridad")) {
  categoriaId = 1;
  areaNombre = "Seguridad Informática y Vulnerabilidades";
} else if (textoCompleto.includes("postgres") || textoCompleto.includes("db") || textoCompleto.includes("latencia") || textoCompleto.includes("query")) {
  categoriaId = 2;
  areaNombre = "Rendimiento y Base de Datos";
} else if (textoCompleto.includes("docker") || textoCompleto.includes("nginx") || textoCompleto.includes("cloudflare") || textoCompleto.includes("contenedor")) {
  categoriaId = 3;
  areaNombre = "Infraestructura, Red y Contenedores";
}

// Urgencia GLPI: 5 = Muy alta (critical), 3 = Media (warning/info)
const urgencia = severidad === "critical" ? 5 : 3;

return [{
  json: {
    valido: true,
    titulo: `[${severidad.toUpperCase()}] ${nombreAlerta} (${servicio})`,
    descripcion: `Área responsable: ${areaNombre}\nServicio afectado: ${servicio}\nSeveridad: ${severidad}\nDetalle: ${resumen}\nInicio: ${alerta.startsAt || new Date().toISOString()}`,
    severidad,
    servicio,
    categoriaId,
    areaNombre,
    urgencia
  }
}];

